// thirdparty collects the licenses of the Go modules compiled into Paguro's
// binaries: third_party/LICENSES.txt with every license and notice text (the
// images ship it), and a table in docs/THIRD-PARTY.md between its markers.
//
//	go run ./hack/thirdparty
//
// It fails on a module without a license file or with a license that is not
// known to be compatible with the AGPL-3.0.
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type module struct {
	Path, Version, Dir string
}

// compatible lists the licenses Paguro (AGPL-3.0-only) may include.
var compatible = map[string]bool{
	"Apache-2.0": true, "MIT": true, "BSD-3-Clause": true, "BSD-2-Clause": true,
	"ISC": true, "MPL-2.0": true, "BSD-3-Clause AND Apache-2.0": true,
}

// identify names a license text by its distinctive phrases.
func identify(text string) string {
	t := strings.Join(strings.Fields(text), " ")
	switch {
	case strings.Contains(t, "Apache License") && strings.Contains(t, "Version 2.0"):
		if strings.Contains(t, "Redistribution and use in source and binary forms") {
			return "BSD-3-Clause AND Apache-2.0"
		}
		return "Apache-2.0"
	case strings.Contains(t, "Mozilla Public License Version 2.0"), strings.Contains(t, "Mozilla Public License, version 2.0"):
		return "MPL-2.0"
	case strings.Contains(t, "Permission is hereby granted, free of charge"):
		return "MIT"
	case strings.Contains(t, "Permission to use, copy, modify, and/or distribute this software for any"),
		strings.Contains(t, "Permission to use, copy, modify, and distribute this software for any"):
		return "ISC"
	case strings.Contains(t, "Redistribution and use in source and binary forms"):
		if regexp.MustCompile(`(?i)neither the name|names of its contributors`).MatchString(t) {
			return "BSD-3-Clause"
		}
		return "BSD-2-Clause"
	}
	return "unknown"
}

func main() {
	out, err := exec.Command("go", "list", "-deps", "-json", "./cmd/...").Output()
	if err != nil {
		fail("go list: %v", err)
	}
	mods := map[string]module{}
	dec := json.NewDecoder(bytes.NewReader(out))
	for dec.More() {
		var p struct {
			Standard bool
			Module   *module
		}
		if err := dec.Decode(&p); err != nil {
			fail("decoding go list: %v", err)
		}
		if p.Standard || p.Module == nil || p.Module.Path == "paguro.dev/paguro" {
			continue
		}
		mods[p.Module.Path] = *p.Module
	}
	paths := make([]string, 0, len(mods))
	for p := range mods {
		paths = append(paths, p)
	}
	sort.Strings(paths)

	var texts, table strings.Builder
	texts.WriteString("Third-party software compiled into Paguro's binaries\n" +
		"(generated by hack/thirdparty; Paguro itself: AGPL-3.0-only, see LICENSE)\n")
	table.WriteString("| Module | Version | License |\n|---|---|---|\n")
	var problems []string
	for _, p := range paths {
		m := mods[p]
		files := licenseFiles(m.Dir)
		if len(files) == 0 {
			problems = append(problems, p+": no license file")
			continue
		}
		license := "unknown"
		for _, f := range files {
			b, _ := os.ReadFile(f)
			name := strings.ToUpper(filepath.Base(f))
			if strings.HasPrefix(name, "LICEN") || strings.HasPrefix(name, "COPYING") {
				if l := identify(string(b)); l != "unknown" {
					license = l
				}
			}
			fmt.Fprintf(&texts, "\n%s\n== %s %s – %s\n%s\n\n%s\n", strings.Repeat("=", 78), p, m.Version,
				filepath.Base(f), strings.Repeat("=", 78), strings.TrimSpace(string(b)))
		}
		if !compatible[license] {
			problems = append(problems, fmt.Sprintf("%s: license %s", p, license))
		}
		fmt.Fprintf(&table, "| `%s` | %s | %s |\n", p, m.Version, license)
	}
	if err := os.MkdirAll("third_party", 0o755); err != nil {
		fail("%v", err)
	}
	if err := os.WriteFile("third_party/LICENSES.txt", []byte(texts.String()), 0o644); err != nil {
		fail("%v", err)
	}
	if err := replaceBetween("docs/THIRD-PARTY.md", "<!-- go-modules:begin -->", "<!-- go-modules:end -->", table.String()); err != nil {
		fail("%v", err)
	}
	fmt.Printf("%d modules, third_party/LICENSES.txt and docs/THIRD-PARTY.md written\n", len(paths))
	if len(problems) > 0 {
		fail("needs a decision:\n  %s", strings.Join(problems, "\n  "))
	}
}

// licenseFiles returns the module's license and notice files (top level).
func licenseFiles(dir string) []string {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	var out []string
	for _, e := range entries {
		n := strings.ToUpper(e.Name())
		if !e.IsDir() && (strings.HasPrefix(n, "LICEN") || strings.HasPrefix(n, "COPYING") || strings.HasPrefix(n, "NOTICE")) {
			out = append(out, filepath.Join(dir, e.Name()))
		}
	}
	return out
}

func replaceBetween(path, begin, end, body string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	s := string(b)
	i, j := strings.Index(s, begin), strings.Index(s, end)
	if i < 0 || j < i {
		return fmt.Errorf("%s: markers %s / %s missing", path, begin, end)
	}
	return os.WriteFile(path, []byte(s[:i+len(begin)]+"\n"+body+s[j:]), 0o644)
}

func fail(format string, a ...any) {
	fmt.Fprintf(os.Stderr, "thirdparty: "+format+"\n", a...)
	os.Exit(1)
}
